CodeAssembler& CodeAssemblerFns5::vgatherqps(AsmRegisterXmm op0, AsmMemoryOperand op1) {
	Code code;
	if (register_ext::is_xmm(op1.index())) {
		code = Code::EVEX_Vgatherqps_xmm_k1_vm64x;
	} else if (register_ext::is_ymm(op1.index())) {
		code = Code::EVEX_Vgatherqps_xmm_k1_vm64y;
	} else {
		return set_error("vgatherqps: invalid operands");
	}
	return add_instr_with_state(Instruction::with2(code, op0.register_(), to_memory_operand(op1)), op0.state());
}

